<?php
namespace Tests\Feature;
use App\Accounts\{DeviceAuth,Management,AccountSessionHandler};
use App\Domain\Failure;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Http\Request;
use Illuminate\Session\{Store,ArraySessionHandler};
use Illuminate\Support\Facades\{Cookie,DB,Hash};
use Illuminate\Support\Str;
use Tests\TestCase;
final class AccountsManagementTest extends TestCase {
 use DatabaseTransactions;
 private function user(bool $forced=false,string $role='user'):object{$id=DB::table('users')->insertGetId(['name'=>'Іван 示例','student_id'=>'000'.bin2hex(random_bytes(8)),'password'=>Hash::make('valid-password'),'role'=>$role,'must_change_password'=>$forced]);return DB::table('users')->find($id);}
 private function request(array $state=[],array $cookies=[]):Request{$r=Request::create('/api/me','GET',[], $cookies);$s=new Store('test',new ArraySessionHandler(120));$s->start();$s->put($state);$r->setLaravelSession($s);$this->app->instance('session.store',$s);return $r;}
 private function token():string{foreach(array_reverse(Cookie::getQueuedCookies())as$c)if($c->getName()===DeviceAuth::COOKIE&&$c->getValue())return $c->getValue();$this->fail('No remember cookie');}
 public function test_login_requires_hash_and_preserves_leading_zero_id_without_exposing_id():void{$u=$this->user();$this->postJson('/api/login',['student_id'=>$u->student_id,'password'=>'wrong'])->assertStatus(401);$this->postJson('/api/login',['student_id'=>$u->student_id,'password'=>'valid-password','remember'=>false])->assertOk()->assertJsonPath('user.name',$u->name)->assertJsonMissingPath('user.student_id')->assertJsonMissingPath('user.password');$this->assertSame(0,DB::table('login_devices')->where('user_id',$u->id)->count());}
 public function test_login_rate_limit_and_disabled_user():void{$u=$this->user();for($i=0;$i<5;$i++)$this->postJson('/api/login',['student_id'=>$u->student_id,'password'=>'bad'])->assertStatus(401);$this->postJson('/api/login',['student_id'=>$u->student_id,'password'=>'valid-password'])->assertStatus(429);$v=$this->user();DB::table('users')->where('id',$v->id)->update(['disabled'=>true]);$this->postJson('/api/login',['student_id'=>$v->student_id,'password'=>'valid-password'])->assertStatus(401);}
 public function test_force_change_rejects_initial_password_and_revokes_other_devices():void{$u=$this->user(true);DB::table('users')->where('id',$u->id)->update(['password'=>Hash::make(mb_substr($u->student_id,-6))]);$this->withSession(['uid'=>$u->id])->postJson('/api/password',['password'=>$u->student_id])->assertStatus(422)->assertJsonPath('code','password_predictable');$d=(string)Str::uuid();DB::table('login_devices')->insert(['id'=>$d,'user_id'=>$u->id,'validator_hash'=>str_repeat('a',64),'expires_at'=>now()->addDays(90)]);$this->withSession(['uid'=>$u->id])->postJson('/api/password',['password'=>'a-new-safe-password'])->assertOk()->assertJsonPath('user.must_change_password',false);$updated=DB::table('users')->find($u->id);$this->assertTrue(Hash::check('a-new-safe-password',$updated->password));$this->assertSame(2,$updated->auth_version);$this->assertNotNull(DB::table('login_devices')->find($d)->revoked_at);}
 public function test_normal_change_requires_current_password():void{$u=$this->user();$this->withSession(['uid'=>$u->id])->postJson('/api/password',['password'=>'a-new-safe-password'])->assertStatus(401);$this->withSession(['uid'=>$u->id])->postJson('/api/password',['password'=>'a-new-safe-password','current_password'=>'valid-password'])->assertOk();}
 public function test_stale_auth_version_session_cannot_reauthenticate_or_mutate():void{$u=$this->user(false,'admin');DeviceAuth::revokeUser($u->id);$this->withSession(['uid'=>$u->id,'auth_version'=>1])->getJson('/api/me')->assertJsonPath('user',null);$this->withSession(['uid'=>$u->id,'auth_version'=>1])->postJson('/api/admin/users',['name'=>'N','student_id'=>'123456'])->assertStatus(401);}
 public function test_remember_token_is_hashed_rotated_with_fixed_90_day_expiry_and_short_session():void{config(['session.secure'=>true]);$u=$this->user();$r=$this->request();(new DeviceAuth)->login($r,['student_id'=>$u->student_id,'password'=>'valid-password','remember'=>true]);$token=$this->token();[$id,$validator]=explode('.',$token);$d=DB::table('login_devices')->find($id);$this->assertSame(hash('sha256',$validator),$d->validator_hash);$this->assertNotSame($validator,$d->validator_hash);$this->assertEqualsWithDelta(90*86400,strtotime($d->expires_at)-time(),5);$cookie=Cookie::queued(DeviceAuth::COOKIE);$this->assertTrue($cookie->isSecure());$this->assertTrue($cookie->isHttpOnly());$this->assertSame('lax',$cookie->getSameSite());$this->assertSame(120,config('session.lifetime'));$fresh=$this->request([], [DeviceAuth::COOKIE=>$token]);(new DeviceAuth)->restore($fresh);$this->assertSame($u->id,$fresh->session()->get('uid'));$this->assertNull($fresh->session()->get('reauth_until'));$rotated=DB::table('login_devices')->find($id);$this->assertNotSame($d->validator_hash,$rotated->validator_hash);$this->assertSame($d->validator_hash,$rotated->previous_validator_hash);$this->assertSame($d->expires_at,$rotated->expires_at);$this->assertNotSame($token,$this->token());}
 public function test_remember_rotation_concurrent_grace_and_replay_revocation():void{$u=$this->user();(new DeviceAuth)->login($this->request(),['student_id'=>$u->student_id,'password'=>'valid-password','remember'=>true]);$token=$this->token();[$id]=explode('.',$token);(new DeviceAuth)->restore($this->request([], [DeviceAuth::COOKIE=>$token]));$hash=DB::table('login_devices')->find($id)->validator_hash;$grace=$this->request([], [DeviceAuth::COOKIE=>$token]);(new DeviceAuth)->restore($grace);$this->assertSame($u->id,$grace->session()->get('uid'));$this->assertSame($hash,DB::table('login_devices')->find($id)->validator_hash);DB::table('login_devices')->where('id',$id)->update(['previous_valid_until'=>now()->subSecond()]);$replay=$this->request([], [DeviceAuth::COOKIE=>$token]);(new DeviceAuth)->restore($replay);$this->assertNull($replay->session()->get('uid'));$this->assertNotNull(DB::table('login_devices')->find($id)->revoked_at);}
 public function test_expired_remember_cookie_is_not_authenticated_and_logout_without_session_revokes():void{$u=$this->user();(new DeviceAuth)->login($this->request(),['student_id'=>$u->student_id,'password'=>'valid-password','remember'=>true]);$token=$this->token();[$id]=explode('.',$token);DB::table('login_devices')->where('id',$id)->update(['expires_at'=>now()->subSecond()]);$fresh=$this->request([], [DeviceAuth::COOKIE=>$token]);(new DeviceAuth)->restore($fresh);$this->assertNull($fresh->session()->get('uid'));(new DeviceAuth)->logoutDevice($this->request([], [DeviceAuth::COOKIE=>$token]));$this->assertNotNull(DB::table('login_devices')->find($id)->revoked_at);}
 public function test_malformed_remember_uuid_is_rejected_before_database_uuid_cast():void{$r=$this->request([], [DeviceAuth::COOKIE=>str_repeat('-',36).'.'.str_repeat('a',64)]);(new DeviceAuth)->restore($r);$this->assertNull($r->session()->get('uid'));(new DeviceAuth)->logoutDevice($r);$this->assertNull($r->session()->get('uid'));}
 public function test_database_sessions_write_authority_version_and_reject_revoked_device_or_stale_write():void{$u=$this->user();$d=(string)Str::uuid();DB::table('login_devices')->insert(['id'=>$d,'user_id'=>$u->id,'validator_hash'=>str_repeat('a',64),'expires_at'=>now()->addDays(90)]);$r=$this->request(['uid'=>$u->id,'auth_version'=>1,'device_id'=>$d]);$h=new AccountSessionHandler(DB::connection(),'sessions',120,$this->app);$h->write($r->session()->getId(),'test');$row=DB::table('sessions')->find($r->session()->getId());$this->assertSame($u->id,$row->user_id);$this->assertSame(1,$row->auth_version);$this->assertSame($d,$row->device_id);DB::table('login_devices')->where('id',$d)->update(['revoked_at'=>now()]);$h->write($r->session()->getId(),'stale');$this->assertNull(DB::table('sessions')->find($r->session()->getId())->user_id);$r->session()->forget('device_id');DeviceAuth::revokeUser($u->id);$new=new AccountSessionHandler(DB::connection(),'sessions',120,$this->app);$new->write('stale-session-id','stale');$this->assertNull(DB::table('sessions')->find('stale-session-id')->user_id);}
 public function test_revoking_user_removes_sessions_tickets_and_share_grants():void{$u=$this->user();$c=DB::table('courses')->insertGetId(['name'=>'Physics']);$l=DB::table('lessons')->insertGetId(['name'=>'Lesson','course_id'=>$c,'creator_id'=>$u->id,'target_language'=>'zh','idempotency_key'=>(string)Str::uuid()]);$sid='revoked-'.Str::random(20);DB::table('sessions')->insert(['id'=>$sid,'user_id'=>$u->id,'auth_version'=>1,'payload'=>'','last_activity'=>time()]);DB::table('ws_tickets')->insert(['hash'=>hash('sha256',$sid),'lesson_id'=>$l,'user_id'=>$u->id,'session_id'=>$sid,'expires_at'=>now()->addMinutes(2)]);$share=(string)Str::uuid();DB::table('lesson_shares')->insert(['id'=>$share,'lesson_id'=>$l,'token_hash'=>hash('sha256','share'),'token_encrypted'=>'fixture']);DB::table('share_grants')->insert(['session_id'=>$sid,'share_id'=>$share,'share_version'=>1]);DeviceAuth::revokeUser($u->id);$this->assertDatabaseMissing('sessions',['id'=>$sid]);$this->assertDatabaseMissing('ws_tickets',['session_id'=>$sid]);$this->assertDatabaseMissing('share_grants',['session_id'=>$sid]);}
 public function test_login_regeneration_preserves_visitor_share_grant_and_logout_removes_it():void{$u=$this->user();$c=DB::table('courses')->insertGetId(['name'=>'Private','guest_access'=>'link']);$l=DB::table('lessons')->insertGetId(['name'=>'Lesson','course_id'=>$c,'creator_id'=>$u->id,'target_language'=>'zh','idempotency_key'=>(string)Str::uuid()]);$share=\App\Sharing\SharingService::ensure($l);$r=$this->request(['lesson_share_grants'=>[$share->id=>1]]);$old=$r->session()->getId();DB::table('sessions')->insert(['id'=>$old,'payload'=>base64_encode(serialize($r->session()->all())),'last_activity'=>time()]);DB::table('share_grants')->insert(['session_id'=>$old,'share_id'=>$share->id,'share_version'=>1]);(new DeviceAuth)->login($r,['student_id'=>$u->student_id,'password'=>'valid-password']);$new=$r->session()->getId();$this->assertNotSame($old,$new);$this->assertDatabaseMissing('share_grants',['session_id'=>$old]);$this->assertDatabaseHas('share_grants',['session_id'=>$new,'share_id'=>$share->id]);$this->assertSame(1,$r->session()->get('lesson_share_grants.'.$share->id));(new DeviceAuth)->logoutDevice($r);$this->assertDatabaseMissing('share_grants',['session_id'=>$new]);$this->assertNull($r->session()->get('lesson_share_grants'));}
 public function test_device_revocation_cannot_be_bypassed_with_cached_session_and_cannot_revoke_other_users():void{$u=$this->user();$other=$this->user();$d=(string)Str::uuid();DB::table('login_devices')->insert(['id'=>$d,'user_id'=>$u->id,'validator_hash'=>str_repeat('a',64),'expires_at'=>now()->addDays(90)]);$this->withSession(['uid'=>$other->id])->deleteJson('/api/devices/'.$d)->assertStatus(404);DB::table('login_devices')->where('id',$d)->update(['revoked_at'=>now()]);$this->withSession(['uid'=>$u->id,'device_id'=>$d])->getJson('/api/me')->assertJsonPath('user',null);}
 public function test_database_session_driver_is_registered_for_real_http_login():void{config(['session.driver'=>'database']);$this->app['session']->forgetDrivers();$this->app->forgetInstance('session.store');$u=$this->user();$response=$this->postJson('/api/login',['student_id'=>$u->student_id,'password'=>'valid-password','remember'=>true])->assertOk();$this->assertInstanceOf(AccountSessionHandler::class,$this->app['session.store']->getHandler());$row=DB::table('sessions')->where('user_id',$u->id)->first();$this->assertNotNull($row);$this->assertSame(1,$row->auth_version);$this->assertNotNull($row->device_id);$this->assertNotNull($response->getCookie(DeviceAuth::COOKIE));$this->assertNotNull($response->getCookie('classroom_session'));}
 public function test_short_session_logout_and_regeneration_tombstones_reject_late_parallel_write():void{$u=$this->user();$r=$this->request(['uid'=>$u->id,'auth_version'=>1]);$old=$r->session()->getId();$h=new AccountSessionHandler(DB::connection(),'sessions',120,$this->app);$data=serialize($r->session()->all());$h->write($old,$data);(new DeviceAuth)->logoutDevice($r);$stale=$this->request(['uid'=>$u->id,'auth_version'=>1]);$late=new AccountSessionHandler(DB::connection(),'sessions',120,$this->app);$this->assertTrue($late->write($old,$data));$this->assertSame('',$late->read($old));$this->assertDatabaseMissing('sessions',['id'=>$old]);$this->assertDatabaseHas('session_revocations',['id_hash'=>hash('sha256',$old)]);$active=$stale->session()->getId();$late->write($active,$data);DeviceAuth::regenerate($stale);$this->assertTrue($late->write($active,$data));$this->assertDatabaseMissing('sessions',['id'=>$active]);$this->assertSame('',$late->read($active));}
 public function test_revoked_old_cookie_get_creates_fresh_visitor_session_for_csrf():void{config(['session.driver'=>'database']);$this->app['session']->forgetDrivers();$this->app->forgetInstance('session.store');$u=$this->user();$this->postJson('/api/login',['student_id'=>$u->student_id,'password'=>'valid-password'])->assertOk();$old=$this->app['session.store']->getId();DeviceAuth::discardSessions([$old]);$this->app['session']->forgetDrivers();$this->app->forgetInstance('session.store');$response=$this->withCookie('classroom_session',$old)->getJson('/api/me')->assertOk()->assertJsonPath('user',null);$new=$response->getCookie('classroom_session')->getValue();$this->assertNotSame($old,$new);$this->assertFalse(DeviceAuth::isRevoked($new));$this->assertDatabaseHas('sessions',['id'=>$new,'user_id'=>null]);}
 public function test_admin_only_and_recent_auth_for_sensitive_operations():void{$u=$this->user();$this->withSession(['uid'=>$u->id])->getJson('/api/admin/users')->assertStatus(403);$admin=$this->user(false,'admin');$this->withSession(['uid'=>$admin->id])->postJson('/api/admin/users/'.$u->id.'/reset-password',['confirm'=>true])->assertStatus(403)->assertJsonPath('code','reauth_required');$this->withSession(['uid'=>$admin->id])->postJson('/api/reauth',['password'=>'valid-password'])->assertOk();$this->postJson('/api/admin/users/'.$u->id.'/reset-password',['confirm'=>true])->assertOk();$fresh=DB::table('users')->find($u->id);$this->assertTrue($fresh->must_change_password);$this->assertTrue(Hash::check(mb_substr($u->student_id,-6),$fresh->password));}
 public function test_user_management_normalizes_id_forbids_whitespace_and_protects_last_admin():void{$admin=$this->user(false,'admin');$sid='000'.bin2hex(random_bytes(8));$new=Management::createUser($admin->id,['name'=>' Іван ','student_id'=>' '.$sid.' ']);$this->assertSame($sid,$new['student_id']);$this->assertSame('Іван',$new['name']);$this->assertSame('user',$new['role']);$this->assertTrue($new['must_change_password']);$this->assertArrayNotHasKey('password',$new);$this->assertTrue(Hash::check(mb_substr($sid,-6),DB::table('users')->find($new['id'])->password));$this->withSession(['uid'=>$admin->id,'reauth_until'=>time()+900])->postJson('/api/admin/users',['name'=>'Bad','student_id'=>'000 123'])->assertStatus(422);$this->postJson('/api/admin/users',['name'=>'Bad','student_id'=>$sid])->assertStatus(409)->assertJsonPath('code','student_id_exists');DB::table('users')->where('role','admin')->where('id','<>',$admin->id)->update(['disabled'=>true]);$this->patchJson('/api/admin/users/'.$admin->id,['disabled'=>true])->assertStatus(409)->assertJsonPath('code','last_admin_required');$this->patchJson('/api/admin/users/'.$new['id'],['student_id'=>'00 0000'])->assertStatus(422);$this->assertDatabaseHas('users',['id'=>$new['id'],'student_id'=>$sid]);}
 public function test_courses_sort_archive_keeps_history_and_soft_delete_rejects_active_lesson():void{$admin=$this->user(false,'admin');$c=Management::course($admin->id,null,['name'=>'Physics','sort_order'=>8]);$l=DB::table('lessons')->insertGetId(['name'=>'Lesson','course_id'=>$c['id'],'creator_id'=>$admin->id,'target_language'=>'zh','status'=>'ended','idempotency_key'=>(string)Str::uuid()]);Management::course($admin->id,$c['id'],['archived'=>true,'sort_order'=>1]);$this->getJson('/api/lessons/'.$l)->assertOk();$this->withSession(['uid'=>$admin->id])->postJson('/api/courses/'.$c['id'].'/lessons',['name'=>'New','idempotency_key'=>(string)Str::uuid()])->assertStatus(404);Management::deleteCourse($admin->id,$c['id']);$this->getJson('/api/lessons/'.$l)->assertStatus(404);$this->getJson('/api/admin/courses')->assertJsonMissing(['id'=>$c['id']]);$this->getJson('/api/admin/courses?deleted=1')->assertJsonFragment(['id'=>$c['id']]);$this->assertDatabaseHas('lessons',['id'=>$l]);$active=Management::course($admin->id,null,['name'=>'Active']);DB::table('lessons')->insert(['name'=>'Live','course_id'=>$active['id'],'creator_id'=>$admin->id,'target_language'=>'zh','idempotency_key'=>(string)Str::uuid()]);$this->withSession(['uid'=>$admin->id,'reauth_until'=>time()+900])->deleteJson('/api/admin/courses/'.$active['id'],['confirm'=>true])->assertStatus(409)->assertJsonPath('code','course_has_active_lesson');}
}
